pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));
        vm.assume(caller != address(this));
        vm.assume(caller != newOwner);
        // Transfer ownership to newOwner
        c.transferOwnership(newOwner);
        address ownerBefore = c.owner();
        // Call owner() from a different caller
