// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address newOwner) public {
        // newOwner can be any address; the default `vm.assume` block allows address(0)
        // record current owner
        address prevOwner = c.owner();
        vm.prank(prevOwner);
        // wrap call to catch potential revert
        bool succeeded;
        try c.transferOwnership(newOwner) { succeeded = true; } catch { succeeded = false; }
        if (succeeded) {
            // when transfer succeeds, owner MUST equal newOwner
            // the mutant allows newOwner=address(0), so the assertion fails for newOwner==address(0)
            assertEq(c.owner(), newOwner);
        } else {
            // if transfer reverted, owner must remain unchanged
            assertEq(c.owner(), prevOwner);
        }
    }
}
